PROMPT5_BY_ID = {p["id"]: p for p in PROMPTS5}


def prompt5_txt() -> str:
    parts = ["ПРОМПТЫ УРОКА 5 · ДПО-1 · Социальная инженерия и безопасность при использовании ИИ",
             "Все данные в промптах условные. Реальные имена, номера и рабочие данные не вставляйте.",
             "Политика информационной безопасности Концерна ВКО «Алмаз – Антей» и локальные акты предприятия имеют приоритет.\n"]
    for p in PROMPTS5:
        parts.append(f"=== {p['id']} · {p['title']} ===\n{p['description']}\n\n{p['content']}\n")
    return "\n".join(parts)
